      if (options.resume === false) return void printStatus(state);
      await drive(state, config, store, Boolean(options.discover), Boolean(options.json), { entry: "existing" });
    }));

  op.command("status")
    .argument("[id]", "Operation id (default: all operations in this workspace)")
    .option("-w, --workspace <path>", "Workspace directory (default: current directory)")
    .option("-j, --json", "JSON output")
    .option("--dag", "Read-only view: work-unit DAG, resource eligibility and the open decision")
    .option("--replay", "Read-only replay: the recorded event timeline, oldest first")
    .option("--events <count>", "Events to include with --dag (newest kept)", "20")
    .description("Show operation state, parked work, wake time and pending decisions")
    .action(operationAction((id: string | undefined, options: any) => {
      const store = new OperationStore(path.resolve(options.workspace ?? process.cwd()));
/**
 * /team: an orchestration strategy over the convergence foundation.
 *
 * A team is a durable operation whose work units are roles with real dependencies. Every role runs through the same
 * lower path as any scheduled unit — a truthful agent turn with provider recovery and context admission, on a
 * resource chosen by qualification and eligibility, with durable state, replay safety and cancellation — and the
 * team is COMPLETE only when every required role is COMPLETE. A role whose turn did not establish a result is
 * BLOCKED on a decision, never reported as done.
 */
import { randomUUID } from "node:crypto";
import * as fs from "node:fs";
import * as path from "node:path";
import { SecurityManager } from "./security.js";
import { inputPathProtection } from "./core/specialist_inputs.js";
import { redactForPersistence } from "./core/persistence_protection.js";
import { isRequired, newOperation, type DurableOperationState, type OperationEvent, type WorkUnit, type WorkUnitSpec } from "./core/operation.js";
import { AgentWorkUnitExecutor, driveOperation, OperationStore, resourcesFromConfig, type WorkUnitExecutor } from "./core/operation_runner.js";
import type { RecoveryClock } from "./core/provider_recovery.js";
import type { ResourceDescriptor } from "./core/resources.js";
import { ROLE_PROFILES, ROLE_REQUIREMENTS, roleRequirements, SPECIALIST_CONTRACTS, isSpecialistRole, parseLeadingSpecialistInputs, type AgentRole } from "./core/roles.js";
import { mergeOperationPolicy } from "./config.js";
import type { HarnessConfig } from "./types.js";

export { ROLE_PROFILES, ROLE_REQUIREMENTS, type AgentRole, type TeamRole, type RoleProfile } from "./core/roles.js";

export const TEAM_ROLES: AgentRole[] = ["researcher", "architect", "implementer", "tester", "reviewer"];

/** Every role `/team` accepts as a single-role target: the five team roles and the specialist roles. */
export const TEAM_TARGET_ROLES: AgentRole[] = [...TEAM_ROLES, ...(Object.keys(SPECIALIST_CONTRACTS) as AgentRole[])];

export type TeamTarget = AgentRole | "full";

const UNIT_ID: Partial<Record<AgentRole, string>> = { researcher: "research", architect: "design", implementer: "implement", tester: "verify", reviewer: "review" };

/** Role turns segment at 15 steps (durable checkpoint boundary; continues until completion, stagnation or cancel unless --no-continuation is set). */
const ROLE_MAX_STEPS = 15;

/**
 * The work graph for a team target. The full workflow's chain is a genuine data dependency (design needs the
 * research, implementation needs the design, verification needs the implementation). Independent review needs only
 * the implementation, so it runs alongside verification, and must use a model the implementation did not use.
 */
export function teamUnits(target: TeamTarget, objective: string, opts: { independentReview?: boolean; workspace?: string } = {}): WorkUnitSpec[] {
  const unit = (role: AgentRole, dependsOn: string[], independentOf?: string[]): WorkUnitSpec => {
    // A specialist target takes its contract inputs as leading name=value words; they are enforced at admission.
    const parsed = isSpecialistRole(role) ? parseLeadingSpecialistInputs(role, objective) : undefined;
    return {
    id: UNIT_ID[role] ?? role,
    title: ROLE_PROFILES[role].title,
    role,
    prompt: parsed ? parsed.task : objective,
    ...(parsed && (Object.keys(parsed.inputs).length || Object.keys(parsed.files).length)
      ? { inputs: { ...parsed.inputs, ...(Object.keys(parsed.files).length ? readTeamFileInputs(requireWorkspace(opts.workspace), parsed.files) : {}) } }
      : {}),
    dependsOn,
    requires: roleRequirements(role, independentOf ? { independentOf } : {}),
    ...(ROLE_REQUIREMENTS[role].taskClass ? { taskClass: ROLE_REQUIREMENTS[role].taskClass } : {}),
    };
  };
  if (target !== "full") return [unit(target, [])];
  const units = [unit("researcher", []), unit("architect", ["research"]), unit("implementer", ["design"]), unit("tester", ["implement"])];
  if (opts.independentReview) units.push(unit("reviewer", ["implement"], ["implement"]));
  return units;
}

function requireWorkspace(workspace: string | undefined): string {
  if (!workspace) throw new Error("@file: inputs need a workspace");
  return workspace;
}

/** Largest file a `/team name=@file:path` input reads; the text is persisted with the operation. */
const MAX_TEAM_FILE_INPUT_BYTES = 64 * 1024;

/**
 * Reads the `@file:` inputs of a `/team` specialist target. The file must be a regular file inside the workspace and
 * not protected by the same security policy the read_file tool applies (checked on the path as written and on where
 * it really points, so a symlink cannot reach a protected file). The text is capped and credential-redacted before it
 * is persisted with the operation.
 */
function readTeamFileInputs(workspace: string, files: Record<string, string>): Record<string, string> {
  const root = fs.realpathSync(workspace);
  const security = new SecurityManager(root);
  const out: Record<string, string> = {};
  for (const [name, written] of Object.entries(files)) {
    const file = path.resolve(root, written);
    let real: string;
    try {
      real = fs.realpathSync(file);
    } catch {
      throw new Error(`Input '${name}': file '${written}' not found`);
    }
    if (real !== root && !real.startsWith(root + path.sep)) throw new Error(`Input '${name}': '${written}' is outside the workspace`);
    for (const candidate of [path.relative(root, file), path.relative(root, real)]) {
      const protection = inputPathProtection(security, candidate);
      if (protection) throw new Error(`Input '${name}': '${written}' is protected (${protection})`);
    }
    const stat = fs.statSync(real);
    if (!stat.isFile() || stat.size > MAX_TEAM_FILE_INPUT_BYTES) throw new Error(`Input '${name}': '${written}' is not a regular file of at most ${MAX_TEAM_FILE_INPUT_BYTES} bytes`);
    out[name] = redactForPersistence(fs.readFileSync(real, "utf8"));
  }
  return out;
}

export interface TeamRunOptions {
  signal?: AbortSignal;
  onEvent?: (e: OperationEvent) => void;
  /** Add an independent reviewer to the full workflow. */
  independentReview?: boolean;
  /** Interactive callers: waits longer than this return a durable WAITING team instead of blocking the prompt. */
  maxInProcessWaitMs?: number;
  /** Defaults: the workspace operation store, config-derived resources, agent-turn executor, real clock. */
  store?: OperationStore;
  resources?: ResourceDescriptor[];
  executor?: WorkUnitExecutor;
  clock?: RecoveryClock;
  id?: string;
}

export interface TeamOutcome {
  operation: DurableOperationState;
  /** True only when the operation is COMPLETE: every required role established its result. */
  success: boolean;
  report: string;
}

export class TeamOrchestrator {
  constructor(
    private readonly config: HarnessConfig,
    private readonly opts: TeamRunOptions = {},
  ) {}

  plan(target: TeamTarget, objective: string): DurableOperationState {
    const now = this.opts.clock?.now() ?? Date.now();
    const resources = this.opts.resources ?? resourcesFromConfig(this.config);
    const policy = mergeOperationPolicy(this.config.operationPolicy, undefined);
    return newOperation(this.opts.id ?? `team-${randomUUID().slice(0, 8)}`, objective, teamUnits(target, objective, { ...this.opts, workspace: this.config.workspace }), resources, now, policy);
  }

  async run(target: TeamTarget, objective: string): Promise<TeamOutcome> {
    return this.drive(this.plan(target, objective));
  }

  async drive(state: DurableOperationState): Promise<TeamOutcome> {
    const store = this.opts.store ?? new OperationStore(this.config.workspace);
    const executor =
      this.opts.executor ?? new AgentWorkUnitExecutor({ baseConfig: { ...this.config, maxSteps: Math.min(this.config.maxSteps, ROLE_MAX_STEPS) } });
    const operation = await driveOperation(state, {
      store,
      executor,
      signal: this.opts.signal,
      workspace: this.config.workspace,
      ...(this.opts.clock ? { clock: this.opts.clock } : {}),
      ...(this.opts.onEvent ? { onEvent: this.opts.onEvent } : {}),
      ...(this.opts.maxInProcessWaitMs !== undefined ? { maxInProcessWaitMs: this.opts.maxInProcessWaitMs } : {}),
    });
    const success = operation.status === "COMPLETE";
    return { operation, success, report: teamReport(operation) };
  }
}

function independence(op: DurableOperationState, u: WorkUnit): string {
  const of = u.requires.independentOf ?? [];
  if (!of.length || u.status !== "COMPLETE") return "";
  if (u.result?.overriding?.some((r) => r.includes("not independent"))) return " — NOT independent (operator decision)";
  const others = of.flatMap((id) => op.units.find((x) => x.id === id)?.modelsUsed ?? []);
  return ` — independent of ${of.join(", ")} (${u.modelsUsed.join(", ")} vs ${others.join(", ") || "none"})`;
}

function unitLine(op: DurableOperationState, u: WorkUnit): string[] {
  const head = `[${(u.role ?? u.id).toUpperCase()}] ${u.status}${isRequired(u) ? "" : " (advisory)"}`;
  switch (u.status) {
    case "COMPLETE":
      return [`${head} on ${u.result!.resourceId} (${u.result!.outcome})${independence(op, u)}`, `  ${u.result!.summary}`];
    case "PARKED":
      return [`${head} — ${u.parked!.reason}; eligible again ${u.parked!.wakeAt}`];
    case "BLOCKED":
      if (!u.blocked) return [`${head}${u.dropped ? " — dropped by operator" : ""}`];
      return [
        `${head} — ${u.blocked.reason}`,
        `  Decision ${u.blocked.decision.id}: ${u.blocked.decision.question}`,
        ...u.blocked.decision.options.map((o) => `    [${o.id}] ${o.label}`),
        `  Apply with: nexus operation decide ${op.id} ${u.blocked.decision.id} <option> [--note <text>]`,
      ];
    case "WAITING_ON_DEPENDENCY":
      return [`${head} — needs ${u.dependsOn.filter((d) => op.units.find((x) => x.id === d)?.status !== "COMPLETE").join(", ")}`];
    default:
      return [`${head}${u.assignment ? ` on ${u.assignment.resourceId}` : ""}`];
  }
}

export function teamReport(op: DurableOperationState): string {
  const lines = [`=== Team ${op.id}: ${op.status} ===`, `Objective: ${op.objective}`, ""];
  for (const u of op.units) lines.push(...unitLine(op, u), "");
  if (op.wait) lines.push(`Waiting until ${op.wait.wakeAt}: ${op.wait.reason}`);
  lines.push(op.status === "COMPLETE" ? "Result: COMPLETE" : `Result: NOT COMPLETE (${op.status})`);
  if (op.status === "WAITING" || op.status === "CANCELLED") lines.push(`Resume with: nexus operation resume ${op.id}`);
  return lines.join("\n");
}
import * as path from "node:path";
import { encodeImageFile, formatVisionContent } from "../image.js";
import type { McpClientManager } from "../mcp.js";
import type { OperationEvent } from "../core/operation.js";
import { AgentRole, TEAM_TARGET_ROLES, TeamOrchestrator } from "../team.js";
import { SlashContext, SlashHandler, SlashOutcome, reply } from "./catalog.js";
import { recall } from "./session_commands.js";

const IMAGE_PROMPT = "Please analyze this image, describe its contents, and provide relevant technical solutions.";
const ROLES: string[] = TEAM_TARGET_ROLES;
const TEAM_USAGE = `Usage: /team <${[...TEAM_TARGET_ROLES, "full"].join("|")}> [--independent-review] <objective>`;
/** Longer waits leave the team WAITING durably (resumable) instead of holding the prompt. */
const TEAM_INTERACTIVE_WAIT_MS = 60_000;

function planLines(phases: Array<{ name: string; status: string }>): string[] {
  return phases.map((p, index) => `${index + 1}. ${p.status === "completed" ? "[x]" : p.status === "in_progress" ? "[~]" : "[ ]"} ${p.name}`);
}

function plan({ host, args }: SlashContext): SlashOutcome {
  const agent = host.app.getAgent();
  const [sub, ...rest] = args.trim().split(/\s+/).filter(Boolean);
  const phases = [...agent.getActivePlan()];
  const show = (lead: string) => reply("plan", [lead, ...planLines(agent.getActivePlan())].filter(Boolean).join("\n"));
  switch (sub?.toLowerCase()) {
    case "add": {
      const name = rest.join(" ");
      if (!name) return reply("plan", "Usage: /plan add <phase description>", false);
      agent.setActivePlan([...phases, { name, status: "pending" }]);
      return show(`Added: ${name}`);
    }
    case "start":
    case "done":
    case "complete": {
      const index = Number.parseInt(rest[0] ?? "", 10) - 1;
      if (!(index >= 0 && index < phases.length)) return reply("plan", `Phase number must be 1..${phases.length}.`, false);
      const started = sub.toLowerCase() === "start";
      phases[index] = { ...phases[index], status: started ? "in_progress" : "completed" };
      agent.setActivePlan(phases);
      return show(`Phase ${index + 1} ${started ? "in progress" : "completed"}.`);
    }
    case "clear":
      agent.setActivePlan([]);
      return reply("plan", "Plan cleared.");
    default:
      return phases.length ? show("") : reply("plan", "No active plan. Add a phase with /plan add <description>.");
  }
}

function knowledge({ host, args }: SlashContext): SlashOutcome {
  const graph = host.app.getAgent().getKnowledgeGraph();
  const [sub, key, ...value] = args.trim().split(/\s+/).filter(Boolean);
  const action = sub?.toLowerCase();
  if (action === "set" && key) {
    const entry = graph.set(key, value.join(" "), "rule");
    return reply("knowledge", `Saved [${entry.category}] ${entry.key}`);
  }
  if (action === "delete" && key) return graph.delete(key) ? reply("knowledge", `Deleted ${key}`) : reply("knowledge", `Not found: ${key}`, false);
  const entries = graph.list();
  return entries.length
    ? reply("knowledge", entries.map((e) => `• [${e.category}] ${e.key}: ${e.value}`).join("\n"))
    : reply("knowledge", "No knowledge entries. Add one with /knowledge set <key> <rule>.");
}

function skills({ host }: SlashContext): SlashOutcome {
  const manager = host.app.getAgent().getSkillManager();
  const list = manager.listSkills();
  const untrustedList = manager.listUntrustedSkills();
  if (!list.length && !untrustedList.length) {
    return reply("skills", "No skills found. Add one under ~/.nexus/skills/<name>/SKILL.md or .nexus/skills/, or run /skill init <name>.");
  }
  const lines: string[] = [];
  for (const s of list) {
    lines.push(`• ${s.name} (${s.path})`);
    lines.push(`    ${s.description}`);
  }
  for (const s of untrustedList) {
    lines.push(`• ${s.name} (${s.path}) [untrusted (not loaded)]`);
    lines.push(`    ${s.description} — run 'nexus trust .' to enable workspace skills`);
  }
  lines.push("");
  lines.push("Show one with /skill <name>.");
  return reply("skills", lines.join("\n"));
}

function skill({ host, args }: SlashContext): SlashOutcome {
  const manager = host.app.getAgent().getSkillManager();
  const text = args.trim();
  if (!text) return reply("skill", "Usage: /skill <name> or /skill init <name>", false);
  if (text === "init" || text.startsWith("init ")) {
    const name = text.slice(4).trim();
    if (!name) return reply("skill", "Usage: /skill init <name>", false);
    return reply("skill", `Scaffolded ${name} at ${manager.scaffoldSkill(name).skillPath}`);
  }
  const found = manager.getSkill(text);
  if (found) {
    return reply("skill", `${found.name} · ${found.path}\n\n${found.content}`);
  }
  const untrusted = manager.getUntrustedSkill(text);
  if (untrusted) {
    return reply("skill", `Skill ${text} is in an untrusted workspace [untrusted (not loaded)]. Run 'nexus trust .' to trust this workspace.`, false);
  }
  return reply("skill", `Skill ${text} not found. /skills lists the available ones.`, false);
}

async function mcpAdd(manager: McpClientManager, words: string[]): Promise<SlashOutcome> {
  const usage = "Usage: /mcp add <name> stdio <command...>  or  /mcp add <name> sse|websocket <url>";
  const [name, transport, ...rest] = words;
  if (!name || !transport || !rest.length) return reply("mcp", usage, false);
  const kind = transport.toLowerCase();
  let config: Record<string, unknown>;
  if (kind === "stdio") config = { transport: "stdio", command: rest[0], args: rest.slice(1) };
  else if (kind === "sse" || kind === "websocket") config = { transport: kind, url: rest[0] };
  else return reply("mcp", usage, false);
  const result = await manager.addServer(name, config as any, true);
  return result.success
    ? reply(
        "mcp",
        result.persisted === false
          ? `Connected to ${name}: ${result.toolCount} tools, ${result.resourceCount} resources, ${result.promptCount} prompts. Configuration was NOT saved: ${result.persistError}`
          : `Connected to ${name}: ${result.toolCount} tools, ${result.resourceCount} resources, ${result.promptCount} prompts. Saved to ~/.config/nexus/mcp.json.`
      )
    : reply("mcp", `Connection failed: ${result.error}`, false);
}

async function mcp({ host, args }: SlashContext): Promise<SlashOutcome> {
  const agent = host.app.getAgent();
  await agent.initExtensibility();
  const manager = agent.getMcpManager();
  const words = args.trim().split(/\s+/).filter(Boolean);
  switch (words[0]?.toLowerCase()) {
    case "add":
      return mcpAdd(manager, words.slice(1));
    case "resources": {
      const resources = manager.listResources();
      if (!resources.length) return reply("mcp", "Connected servers expose no resources.");
      const rows = resources.map((r) => `• ${r.name} (${r.uri}) [${r.server}]${r.description ? `\n    ${r.description}` : ""}`);
      return reply("mcp", [...rows, "", "Read one with /mcp resource <uri>."].join("\n"));
    }
    case "resource": {
      const uri = words.slice(1).join(" ");
      if (!uri) return reply("mcp", "Usage: /mcp resource <uri>", false);
      const result = await manager.readResource(uri);
      return result.success ? reply("mcp", result.content || "(empty)") : reply("mcp", `Could not read ${uri}: ${result.error}`, false);
    }
    case "prompts": {
      const prompts = manager.listPrompts();
      if (!prompts.length) return reply("mcp", "Connected servers expose no prompt templates.");
      const rows = prompts.map((p) => {
        const params = p.arguments?.length ? ` (args: ${p.arguments.map((a: any) => a.name).join(", ")})` : "";
        return `• ${p.name}${params} [${p.server}]${p.description ? `\n    ${p.description}` : ""}`;
      });
      return reply("mcp", [...rows, "", "Show one with /mcp prompt <name>."].join("\n"));
    }
    case "prompt": {
      const name = words[1];
      if (!name) return reply("mcp", "Usage: /mcp prompt <name>", false);
      const result = await manager.getPrompt(name);
      return result.success
        ? reply("mcp", [result.description ?? "", JSON.stringify(result.messages, null, 2)].filter(Boolean).join("\n\n"))
        : reply("mcp", `Could not fetch ${name}: ${result.error}`, false);
    }
    default: {
      const servers = manager.listServers();
      if (!servers.length) return reply("mcp", "No MCP servers configured. Add one with /mcp add <name> stdio <command...>.");
      const lines = servers.flatMap((s) => [
        `• ${s.name} [${s.connected ? "connected" : "disconnected"} · ${s.transport}] ${s.command ?? ""}`.trimEnd(),
        `    tools ${s.toolCount} · resources ${s.resourceCount} · prompts ${s.promptCount}`,
      ]);
      const tools = manager.getToolDefinitions();
      if (tools.length) lines.push("", "Tools:", ...tools.map((t) => `  ${t.function.name}: ${t.function.description}`));
      return reply("mcp", lines.join("\n"));
    }
  }
}

async function plugins({ host }: SlashContext): Promise<SlashOutcome> {
  const agent = host.app.getAgent();
  await agent.initExtensibility();
  const list = agent.getPluginManager().listPlugins();
  if (!list.length) return reply("plugins", "No plugins loaded from ~/.nexus/plugins/ or ~/.config/nexus/plugins/.");
  return reply("plugins", list.map((p) => `• ${p.name}: ${p.description} (custom tools: ${p.customToolCount})`).join("\n"));
}

async function browse({ host, args }: SlashContext): Promise<SlashOutcome> {
  const url = args.trim();
  if (!url) return reply("browse", "Usage: /browse <url>", false);
  const page = await host.app.getAgent().getBrowserDriver().navigate(url);
  return reply("browse", `${page.title} · HTTP ${page.status}\n\n${page.contentSnippet.slice(0, 300)}…`, page.status === 200);
}

/** The first word and the remainder untouched, so a multiline prompt or objective keeps its line breaks. */
function firstWord(args: string): [string, string] {
  const match = /^(\S+)\s*([\s\S]*)$/.exec(args.trim());
  return match ? [match[1], match[2]] : ["", ""];
}

function image({ host, args }: SlashContext): SlashOutcome {
  const [file, rest] = firstWord(args);
  if (!file) return reply("image", "Usage: /image <path> [prompt]", false);
  const prompt = rest || IMAGE_PROMPT;
  const encoded = encodeImageFile(file, host.app.getConfig().workspace);
  if (!encoded.success) return reply("image", `Could not load the image: ${encoded.error}`, false);
  return {
    kind: "turn",
    command: "image",
    prompt: formatVisionContent(prompt, encoded.dataUri),
    label: `${prompt} [image ${path.basename(encoded.filePath)}]`,
    checkpoint: `Vision: ${prompt.slice(0, 30)}`,
  };
}

async function tdd({ host, args, signal }: SlashContext): Promise<SlashOutcome> {
  const issue = args.trim();
  if (!issue) return reply("tdd", "Usage: /tdd <issue description>", false);
  const agent = host.app.getAgent();
  const result = await agent.getSynthesizer().runAutonomousTdd(agent, issue, undefined, { signal, onConfirm: host.confirm(signal) });
  return result.success
    ? reply("tdd", "TDD cycle completed: RED → GREEN → REFACTOR verified.")
    : reply("tdd", `TDD cycle ended at ${result.finalPhase}: ${result.summary}`, false);
}

async function team({ host, args, signal }: SlashContext): Promise<SlashOutcome> {
  const [role, rest] = firstWord(args);
  const independentReview = /^--independent-review\b/.test(rest);
  const objective = rest.replace(/^--independent-review\b\s*/, "").trim();
  if (!role || !objective) return reply("team", TEAM_USAGE, false);
  const name = role.toLowerCase();
  if (name !== "full" && !ROLES.includes(name)) return reply("team", `Unknown role ${role}. Roles: ${[...ROLES, "full"].join(", ")}`, false);
  const events: OperationEvent[] = [];
  const orchestrator = new TeamOrchestrator(host.app.getConfig(), {
    signal,
