  tools.get_goal({}),
  tools.exec_command({cmd:"pwd && git status --short --branch && git rev-parse HEAD && git rev-parse origin/main && git worktree list --porcelain && ls -la /home/mike/nexus-wt | head -40","workdir":"/home/mike/nexus-code","yield_time_ms":1000,"max_output_tokens":2000}),
  tools.exec_command({cmd:"rg -n -i 'nexus-code|v1\\.3\\.0|batch|delegation' /home/mike/.codex/memories/MEMORY.md","workdir":"/home/mike/nexus-code","yield_time_ms":1000,"max_output_tokens":1200})
]);
for (let i=0;i<rs.length;i++){const r=rs[i];text(`RESULT ${i+1}`);if(r.status==="fulfilled"){const v=r.value;if(v?.output!==undefined)text(v.output);else text(v);}else{text(String(r.reason));}}

const rs=await Promise.allSettled([
  tools.exec_command({cmd:"for p in /home/mike/nexus-wt/pa4-orchestration /home/mike/nexus-wt/v130-colorize-tui; do echo \"--- $p\"; git -C \"$p\" status --short --branch; git -C \"$p\" rev-parse HEAD; git -C \"$p\" log -1 --oneline; done; git branch -a --list '*pa4*' '*batch*' '*loop*' '*goal*' '*v130*'","workdir":"/home/mike/nexus-code","yield_time_ms":1000,"max_output_tokens":2000}),
  tools.exec_command({cmd:"find \"$(git rev-parse --git-common-dir)/nexus-claims\" -mindepth 1 -maxdepth 2 -print -exec sh -c 'test -f \"$1/owner.json\" && cat \"$1/owner.json\"' _ {} \\; 2>/dev/null | head -200; tail -80 \"$(git rev-parse --git-common-dir)/nexus-claims.log\" 2>/dev/null","workdir":"/home/mike/nexus-code","yield_time_ms":1000,"max_output_tokens":3000}),
  tools.exec_command({cmd:"git show origin/main:docs/v1.3.0/ROADMAP.md | sed -n '1,260p'; git show origin/main:docs/v1.3.0/PA4_BASELINE.md | sed -n '1,280p'; git show origin/main:docs/v1.3.0/PLAN.md | sed -n '1,260p'","workdir":"/home/mike/nexus-code","yield_time_ms":1000,"max_output_tokens":7000}),
  tools.exec_command({cmd:"gh pr list --state open --limit 50 --json number,title,headRefName,baseRefName,url && gh pr view 659 --json state,mergedAt,mergeCommit,url","workdir":"/home/mike/nexus-code","yield_time_ms":1000,"max_output_tokens":3000})
]);
for(let i=0;i<rs.length;i++){text(`RESULT ${i+1}`);const x=rs[i];if(x.status==="fulfilled"){text(x.value.output);if(x.value.session_id)text(`SESSION_ID=${x.value.session_id}`);}else text(String(x.reason));}

