/**
 * Canonical Capabilities & Model-Visible Tool Registry
 * Nexus Issue #12 — WP-01 (INC-01, CAP-001..007, DEDUP-001..004)
 */

import { ToolDefinition, ExecutionResult } from "../types.js";

import {
  readFileCapability,
  writeFileCapability,
  editFileCapability,
  listDirCapability,
  findFilesCapability,
  deleteFileCapability,
  fileInfoCapability,
  batchReadCapability,
  fileTreeCapability,
  patchFileCapability,
} from "./capability_definitions/fs.js";
import {
  searchCodeCapability,
  searchSymbolsCapability,
  cstSymbolsCapability,
  outlineFileCapability,
  trigramSearchCapability,
  hybridSearchCapability,
} from "./capability_definitions/code_search.js";
import {
  runCommandCapability,
  runTestsCapability,
} from "./capability_definitions/proc.js";
import {
  fetchWebCapability,
  searchWebCapability,
} from "./capability_definitions/net.js";
import {
  taskCompletedCapability,
  spawnSubagentCapability,
  updatePlanCapability,
} from "./capability_definitions/orchestration.js";
import { activateSkillCapability } from "./capability_definitions/skill.js";
import {
  lspHoverCapability,
  lspDefinitionCapability,
  lspDiagnosticsCapability,
} from "./capability_definitions/lsp.js";
import {
  gitStatusCapability,
  gitDiffCapability,
  gitLogCapability,
} from "./capability_definitions/vcs.js";
import {
  browserNavigateCapability,
  browserScreenshotCapability,
  browserClickCapability,
  browserTypeCapability,
  browserConsoleLogsCapability,
} from "./capability_definitions/browser.js";
import { manageKnowledgeCapability } from "./capability_definitions/knowledge.js";

export type CapabilityBackend = "rust_rpc" | "ts_native" | "extension";

/**
 * What a capability can affect (SPEC-01 §5.1). Review mode asks the operator before `write_workspace`, `exec` and
 * `egress`; `context_inject` is gated by workspace trust instead; `read_workspace`, `delegate` (the child's own calls are
 * gated) and `internal` (Nexus's own bookkeeping, no effect outside the conversation) never ask.
 */
export type EffectClass = "read_workspace" | "write_workspace" | "exec" | "egress" | "delegate" | "context_inject" | "internal";

export const EFFECT_CLASSES: readonly EffectClass[] = ["read_workspace", "write_workspace", "exec", "egress", "delegate", "context_inject", "internal"];

/** Whether review mode asks the operator before a capability of this class runs. */
export function needsOperatorDecision(effect: EffectClass): boolean {
  return effect === "write_workspace" || effect === "exec" || effect === "egress";
}

export interface CanonicalCapability {
  /** Canonical capability identifier (e.g., 'fs_read', 'proc_exec') */
  id: string;
  /** Model-visible tool name matching LLM schemas (e.g., 'read_file', 'run_command') */
  modelToolName: string;
  /** Category of capability */
  category:
    | "fs"
    | "code_search"
    | "proc"
    | "vcs"
    | "net"
    | "lsp"
    | "browser"
    | "knowledge"
    | "skill"
    | "orchestration"
    | "extension"
    | string;
  /** Whether the capability performs side effects (read-only mode refuses it) */
  mutating: boolean;
  /** What the capability can affect; decides whether review mode asks before it runs */
  effect: EffectClass;
  /**
   * Whether a successful call changes the workspace content (makes a verifier result stale, counts as a change to
   * verify). Defaults to `mutating`; false for side effects outside the workspace, such as running tests.
   */
  changesWorkspace?: boolean;
  /** Human- and audit-readable side-effect contract */
  sideEffectContract: string;
  /** Backend execution engine type */
  backend: CapabilityBackend;
  /** Exact model tool definition (JSON schema) presented to LLMs */
  toolDefinition: ToolDefinition;
  /** Optional registered capability execution handler */
  handler?: CapabilityHandler;
}

export type CapabilityHandler = (
  args: Record<string, any>,
  context: any
) => Promise<ExecutionResult>;

export class CapabilityRegistry {
  private readonly capabilitiesByToolName = new Map<string, CanonicalCapability>();
  private readonly capabilitiesById = new Map<string, CanonicalCapability[]>();

  constructor(capabilities: CanonicalCapability[] = []) {
    for (const cap of capabilities) {
      this.register(cap);
    }
  }

  /**
   * Register a canonical capability.
   * Throws if a capability with the same modelToolName is already registered.
   */
  public register(capability: CanonicalCapability): void {
    if (!capability || !capability.id || !capability.modelToolName) {
      throw new Error("Invalid capability: id and modelToolName are required.");
    }
    if (!EFFECT_CLASSES.includes(capability.effect)) {
      throw new Error(`Invalid capability '${capability.modelToolName}': effect must be one of ${EFFECT_CLASSES.join(", ")}.`);
    }
    if (this.capabilitiesByToolName.has(capability.modelToolName)) {
      throw new Error(`Duplicate capability registration: model tool '${capability.modelToolName}' is already registered.`);
    }

    this.capabilitiesByToolName.set(capability.modelToolName, capability);

    const list = this.capabilitiesById.get(capability.id) || [];
    list.push(capability);
    this.capabilitiesById.set(capability.id, list);
  }

  /**
   * Unregister a capability by its tool name or canonical ID.
   */
  public unregister(toolNameOrId: string): boolean {
    const cap = this.capabilitiesByToolName.get(toolNameOrId);
    if (cap) {
      this.capabilitiesByToolName.delete(cap.modelToolName);
      const list = this.capabilitiesById.get(cap.id);
      if (list) {
        const filtered = list.filter((c) => c.modelToolName !== cap.modelToolName);
        if (filtered.length > 0) {
          this.capabilitiesById.set(cap.id, filtered);
        } else {
          this.capabilitiesById.delete(cap.id);
        }
      }
      return true;
    }

    if (this.capabilitiesById.has(toolNameOrId)) {
      const caps = this.capabilitiesById.get(toolNameOrId)!;
      for (const c of caps) {
        this.capabilitiesByToolName.delete(c.modelToolName);
      }
      this.capabilitiesById.delete(toolNameOrId);
      return true;
    }

    return false;
  }

  /**
   * Retrieve capability by model tool name.
   */
  public getByToolName(toolName: string): CanonicalCapability | undefined {
    return this.capabilitiesByToolName.get(toolName);
  }

  /**
   * Retrieve capability by canonical capability ID (returns first registered).
   */
  public getById(id: string): CanonicalCapability | undefined {
    const list = this.capabilitiesById.get(id);
    return list && list.length > 0 ? list[0] : undefined;
  }

  /**
   * Retrieve all capabilities matching a canonical ID.
   */
  public getAllById(id: string): CanonicalCapability[] {
    return this.capabilitiesById.get(id) || [];
  }

  /**
   * Check if a model tool name is registered.
   */
  public hasTool(toolName: string): boolean {
    return this.capabilitiesByToolName.has(toolName);
  }

  /**
   * Check if a canonical ID is registered.
   */
  public hasCapability(id: string): boolean {
    return this.capabilitiesById.has(id);
  }

  /**
   * List all registered canonical capabilities.
   */
  public listCapabilities(): CanonicalCapability[] {
    return Array.from(this.capabilitiesByToolName.values());
  }

  /**
   * List all model-visible tool definitions (100% schema parity).
   */
  public listModelTools(): ToolDefinition[] {
    return Array.from(this.capabilitiesByToolName.values()).map((cap) => cap.toolDefinition);
  }

  /**
   * Attach an execution handler to a capability by model tool name or canonical ID.
   */
  public setHandler(toolNameOrId: string, handler: CapabilityHandler): void {
    const cap = this.capabilitiesByToolName.get(toolNameOrId);
    if (cap) {
      cap.handler = handler;
      return;
  }

  public isReadOnly(): boolean {
    return this.readOnly;
  }

  public addGrant(grant: AuthorityGrant): void {
    this.grants.push(grant);
  }

  public clearGrants(): void {
    this.grants = [];
  }

  public getGrants(): AuthorityGrant[] {
    return [...this.grants];
  }

  /**
   * Authority Admission Gate (Stage 3A)
   * Evaluates capability authority, domain isolation, and read-only enforcement.
   */
  public async admit(
    request: InvocationRequest,
    context: InvocationContext
  ): Promise<AdmissionDecision> {
    const actor = request.actor || "agent";
    const domain = request.executionDomain || "agent_orchestration";
    const toolName = request.toolName;

    // Check domain allowlist if configured
    if (this.allowedDomains && !this.allowedDomains.has(domain) && !this.allowedDomains.has("*")) {
      return {
        admitted: false,
        reason: `AUTH-012: Execution domain '${domain}' is not permitted by domain policy.`,
      };
    }

    // Resolve canonical capability
    const capability = this.registry.getByToolName(toolName);
    if (!capability) {
      return {
        admitted: false,
        reason: `AUTH-003: Unrecognized tool name '${toolName}' cannot be mapped to canonical capability.`,
      };
    }

    const effectiveReadOnly = this.readOnly || Boolean(context.readOnly);

    // Read-only gating (AUTH-009, AUTH-010)
    if (effectiveReadOnly) {
      if (capability.id === "proc_exec" || capability.id === "command_execution" || toolName === "run_command") {
        const cmd = request.args?.command;
        if (!isSafeReadOnlyCommand(cmd, this.safeCommandRegex, this.workspace)) {
          return {
            admitted: false,
            reason: `AUTH-010: Read-only mode violation: Command '${cmd}' is not permitted in read-only mode. Only safe inspection commands are permitted.`,
          };
        }
      } else if (capability.mutating) {
        return {
          admitted: false,
          reason: `AUTH-009: Read-only mode violation: Capability '${capability.id}' mutates candidate state and is denied in read-only mode.`,
        };
      }
    }

    // Full-access bypass of further grant checks (AUTH-007, AUTH-008)
    if (this.fullAccess) {
      return {
        admitted: true,
        effectiveScope: "full_access",
      };
    }

    // If explicit grants are defined, evaluate matching grant (AUTH-001, AUTH-006)
    if (this.grants.length > 0) {
      const matchingGrant = this.findMatchingGrant(actor, domain, capability.id, toolName);
      if (!matchingGrant) {
        return {
          admitted: false,
          reason: `AUTH-006: Fail-closed: No authority grant authorizes capability '${capability.id}' for actor '${actor}' in domain '${domain}'.`,
        };
      }

      return {
        admitted: true,
        effectiveScope: matchingGrant.scope,
      };
    }

    // Default workspace authority grant if no explicit grants defined
    return {
      admitted: true,
      effectiveScope: "workspace",
    };
  }

  /**
   * Resource Confinement Gate (Stage 3B)
   * Enforces workspace boundary containment, cwd confinement, and exact/subtree scopes.
   */
  public async confine(
    request: InvocationRequest,
    context: InvocationContext
  ): Promise<ResourceConfinementDecision> {
    const wsRoot = path.resolve(context.workspaceRoot || process.cwd());
    const actor = request.actor || "agent";
    const domain = request.executionDomain || "agent_orchestration";
    const capability = this.registry.getByToolName(request.toolName);
    const capId = capability ? capability.id : request.toolName;

    // In full-access mode, resource confinement is broad (AUTH-007, AUTH-008)
    if (this.fullAccess) {
      return { confined: true };
    }

    // Determine effective scope from matching grant
    let effectiveScope: AuthorityScope = "workspace";
    let allowedResources: string[] | undefined = undefined;

    if (this.grants.length > 0) {
      const grant = this.findMatchingGrant(actor, domain, capId, request.toolName);
      if (grant) {
        effectiveScope = grant.scope;
        allowedResources = grant.resources;
        if (effectiveScope === "full_access") {
          return { confined: true };
        }
      }
    }

    // 1. Verify subprocess cwd confinement (RES-002, AUTH-011)
    if ((capId === "proc_exec" || capId === "command_execution" || request.toolName === "run_command") && request.args?.cwd) {
      const cwdStr = String(request.args.cwd).trim();
      const targetCwd = path.isAbsolute(cwdStr) ? path.normalize(cwdStr) : path.resolve(wsRoot, cwdStr);
      const rel = path.relative(wsRoot, targetCwd);
      if (rel.startsWith("..") || path.isAbsolute(rel)) {
        return {
          confined: false,
          reason: `RES-002: Security Violation: Working directory '${cwdStr}' escapes workspace jail.`,
        };
      }
    }

    // 2. Extract and verify all target resource paths (RES-001, RES-004, AUTH-004, AUTH-005)
    const targets = extractTargetResources(request.toolName, request.args);
    for (const target of targets) {
      const cleanPath = target.trim();
      if (!cleanPath) continue;

      const absTarget = path.isAbsolute(cleanPath)
        ? path.normalize(cleanPath)
        : path.resolve(wsRoot, cleanPath);

      // Verify path stays within workspaceRoot (RES-004)
      const relToWs = path.relative(wsRoot, absTarget);
      if (relToWs.startsWith("..") || path.isAbsolute(relToWs)) {
        return {
          confined: false,
          reason: `RES-004: Security Violation: Path '${cleanPath}' escapes workspace jail.`,
        };
      }

      // Check scope-specific constraints (AUTH-004, AUTH-005)
      if (effectiveScope === "exact") {
        if (!allowedResources || allowedResources.length === 0) {
          return {
            confined: false,
            reason: `AUTH-004: Exact scope grant requires specific resources list.`,
          };
        }
        const matchesExact = allowedResources.some((r) => {
          const absAllowed = path.isAbsolute(r) ? path.normalize(r) : path.resolve(wsRoot, r);
          return absAllowed === absTarget;
        });
        if (!matchesExact) {
          return {
            confined: false,
            reason: `AUTH-005: Security Violation: Path '${cleanPath}' does not match any exact authorized resource (no sibling inheritance).`,
          };
        }
      } else if (effectiveScope === "subtree") {
        if (!allowedResources || allowedResources.length === 0) {
          return {
            confined: false,
            reason: `AUTH-004: Subtree scope grant requires specific resources list.`,
          };
        }
        const matchesSubtree = allowedResources.some((r) => {
          const absAllowed = path.isAbsolute(r) ? path.normalize(r) : path.resolve(wsRoot, r);
          const rel = path.relative(absAllowed, absTarget);
          return !rel.startsWith("..") && !path.isAbsolute(rel);
        });
        if (!matchesSubtree) {
          return {
            confined: false,
            reason: `AUTH-005: Security Violation: Path '${cleanPath}' is outside authorized subtree scope (no sibling inheritance).`,
          };
        }
      }
    }

    return { confined: true };
  }

  /**
   * Creates an AuthorityAdmissionHook for ExecutionSpine.
   */
  public createAdmissionHook(): AuthorityAdmissionHook {
    return (request, context) => this.admit(request, context);
  }

  /**
   * Creates a ResourceConfinementHook for ExecutionSpine.
   */
  public createConfinementHook(): ResourceConfinementHook {
    return (request, context) => this.confine(request, context);
  }

