export interface ExecutionReceipt {
  /** Immutable invocation identity (EXEC-002) */
  invocationId: string;
  /** Owning task identity (EXEC-002) */
  taskId: string;
  /** Actor identity (EXEC-008, EVID-003) */
  actor: string;
  /** Execution domain (EXEC-013, EVID-003) */
  executionDomain: string;
  /** Canonical capability identity (CAP-001) */
  capabilityId: string;
  /** Model-visible tool name */
  toolName: string;
  /** Concrete affected or queried resource paths/targets (CAP-004) */
  targetResources: string[];
  /** Outcome status */
  success: boolean;
  /** Execution output string */
  output: string;
  /** Error message if failed or denied */
  error?: string;
  /** The call may have taken effect, but its executor outcome could not be established. */
  outcomeUnknown?: boolean;
  /** Execution duration in milliseconds */
  durationMs: number;
  /** Whether candidate state was mutated by operation (CAND-001) */
  candidateMutated: boolean;
  /** High-level execution status */
  status: "COMPLETED" | "DENIED" | "FAILED" | "UNKNOWN" | "BLOCKED";
  /** Typed denial reason if status is DENIED */
  denialReason?: string;
  /** ISO 8601 timestamp (EVID-003) */
  timestamp: string;
  /** Whether operation was simulated rather than actual host effect (EXEC-010) */
  simulated: boolean;
  /** Active skill activation id when governed skill attribution is enabled (WP-GS-01) */
  skillActivationId?: string;
  /** Skill name bound to this invocation when attributed */
  skillName?: string;
  /** SHA-256 of the skill body that was activated (WP-GS-02) */
  skillContentDigest?: string;
}

function withSkillAttribution(receipt: ExecutionReceipt, request: InvocationRequest): ExecutionReceipt {
  const a = request.skillAttribution;
  if (!a?.skillActivationId) return receipt;
  return {
    ...receipt,
    ...(a.skillActivationId ? { skillActivationId: a.skillActivationId } : {}),
    ...(a.skillName ? { skillName: a.skillName } : {}),
    ...(a.skillContentDigest ? { skillContentDigest: a.skillContentDigest } : {}),
  };
}

