  for (const ch of command) {
    if (quoteChar) {
      if (ch === quoteChar) quoteChar = "";
      else current += ch;
      started = true;
      continue;
    }
    if (ch === '"' || ch === "'") {
      quoteChar = ch;
      started = true;
      continue;
    }
    if (/\s/.test(ch)) {
      if (started) {
        words.push(current);
        current = "";
        started = false;
      }
      continue;
    }
    current += ch;
    started = true;
  }
  if (quoteChar) return null;
  if (started) words.push(current);
  return words;
}

