test("captures discovered verifier baseline before a subagent can mutate the workspace", async () => {
  const savedHome = process.env.HOME;
  const savedXdgConfigHome = process.env.XDG_CONFIG_HOME;
  const home = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-discovered-verifier-subagent-home-"));
  process.env.HOME = home;
  process.env.XDG_CONFIG_HOME = path.join(home, ".config");
  const workspace = setupWorkspace();
  const gateway = await startGateway((_n, body) => {
    const isSubagent = JSON.stringify(body?.messages ?? []).includes("[Subagent Objective]");
    const toolResults = (body?.messages ?? []).filter((message: any) => message.role === "tool").length;
    if (isSubagent) {
      return toolResults === 0
        ? {
            kind: "tools",
            calls: [{ name: "edit_file", args: { path: "math.js", old_content: "exports.add = (a, b) => a - b;\n", new_content: "exports.add = (a, b) => a + b;\n" } }],
          }
        : { kind: "text", content: "Fixed the addition implementation." };
    }
    return toolResults === 0
      ? { kind: "tools", calls: [{ name: "spawn_subagent", args: { prompt: "Fix the failing addition test." } }] }
      : toolResults === 1
      ? { kind: "tools", calls: [{ name: "task_completed", args: { summary: "Fixed addition" } }] }
      : { kind: "text", content: "Done." };
  });
  const agent = quiet(new AutonomousAgent({
    endpoint: gateway.url,
    model: "fixture",
    workspace,
    trustedDeliverableFiles: ["math.js"],
    shell: "bash",
    approvalMode: "auto",
    fullAccess: true,
    maxSteps: 5,
    temperature: 0,
    continuation: { ...DEFAULT_CONTINUATION, maxCompletionNudges: 0 },
  } as HarnessConfig));

  try {
    const turn = await agent.runTurn("Use a subagent to fix the failing addition test, then complete the task.");

    assert.equal(fs.readFileSync(path.join(workspace, "math.js"), "utf-8"), "exports.add = (a, b) => a + b;\n");
    assert.equal(turn.outcome, "VERIFIED", `${turn.outcome}: ${turn.reason}: ${turn.detail}`);
    assert.equal(turn.verification?.independent, true);
    assert.equal(turn.unverifiedChangesPending, false);
  });

  test("a delegated helper progresses beyond a short segment while consuming the shared task budget", { timeout: 120_000 }, async () => {
    const gw = await startGateway((n, body) => {
      const sub = allText(body).includes("[Subagent Objective]");
      if (!sub) return n === 1 ? { kind: "tools", calls: [{ name: "spawn_subagent", args: { prompt: "write s1..s20", max_steps: 2 } }] } : text("parent done");
      const written = (body.messages as any[]).filter((m) => m.role === "tool").length;
      return written < 20 ? write(`s/s${written + 1}.txt`) : { kind: "tools", calls: [{ name: "task_completed", args: { summary: "wrote 20 files" } }] };
    });
    const repo = makeRepo();
    const agent = quiet(new AutonomousAgent(cfg(gw.url, repo)));
    try {
      await agent.runTurn("Delegate writing s1..s20 to a helper.");
      assert.ok(fs.existsSync(path.join(repo, "s", "s20.txt")), "the helper should finish while the shared 500-step task budget remains");
    } finally {
      agent.shutdown();
      await gw.close();
      fs.rmSync(repo, { recursive: true, force: true });
    }
  });
});

describe("B. repetition is judged against workspace state", () => {
  test("an unchanged failing command repeated on an unchanged workspace gets a recovery note; after an input change the retry is legitimate", { timeout: 120_000 }, async () => {
    const repo = makeRepo({ "check.sh": "grep -q fixed input.txt || { echo 'FAIL: input not fixed'; exit 1; }\n", "input.txt": "broken\n" });
    const script = (n: number): Reply => {
      if (n <= 2) return run("sh check.sh"); // twice: a legitimate re-check, below the threshold
      if (n === 3) return run("printf 'still broken\\n' > input.txt"); // a real input change
      if (n <= 5) return run("sh check.sh"); // same command and same output, but on a new state: not a loop
      if (n === 6) return run("sh check.sh"); // third on that state: a loop
      return text("stopping");
    };
    const gw = await startGateway(script);
    const agent = quiet(new AutonomousAgent(cfg(gw.url, repo, { continuation: { ...DEFAULT_CONTINUATION, maxRecoveries: 2 } })));
    agent.backoffSleep = async () => {};
    try {
      await agent.runTurn("Make check.sh pass.");
      const notesAt = (gw.requests as any[]).map((b, i) => [i + 1, (b.messages as any[]).filter((m) => m.role === "user" && String(m.content).startsWith("[Nexus recovery")).length] as const);
      const firstNote = notesAt.find(([, c]) => c > 0)?.[0];
      assert.equal(firstNote, 7, `no note for the retries after the edit; the first note follows the third run on the edited state (${JSON.stringify(notesAt)})`);
      const loops = agent.getObjective()!.execution!.repetitions.filter((r) => r.count >= 3);
      assert.equal(loops.length, 1);
      assert.match(loops[0].action, /sh check\.sh/);
    } finally {
      agent.shutdown();
      await gw.close();
  });
});

// ---------------------------------------------------------------- I1: spawn_subagent

/** A parent that delegates once, then calls task_completed (and stops in text if that is rejected). */
function delegating(child: (r: Req) => Reply, maxSteps = 3): (r: Req) => Reply {
  return (r) => {
    if (isSubagent(r.body)) return child(r);
    return [{ tools: [{ name: "spawn_subagent", args: { prompt: "do the delegated work", max_steps: maxSteps } }] }, done("parent done")][toolResults(r.body)] ?? { text: "parent stopped" };
  };
}

function delegationResult(agent: AutonomousAgent): string {
  const msg = agent.getMessages().find((m) => m.role === "tool" && m.name === "spawn_subagent");
  return String(msg?.content ?? "");
}

describe("I1: spawn_subagent cannot manufacture success", () => {
  test("a rejected task_completed receipt is not completion: the child keeps working, then reports not completed", async () => {
    await withHome(async () => {
      const gw = await gateway(delegating((r) => (toolResults(r.body) === 0 ? write() : done("sub done"))));
      const repo = makeRepo();
      try {
        const { turn, agent } = await directTurn(cfg(gw, repo, { authoritativeVerifierCommand: "false" }), "delegate the change");
        try {
          const childCompletions = gw.requests.filter((r) => isSubagent(r.body) && toolResults(r.body) >= 1).length;
          assert.ok(childCompletions >= 2, "the child saw its rejected task_completed and kept going");
          assert.match(delegationResult(agent), /^Error executing spawn_subagent: Subagent did not complete/);
          assert.equal(turnSucceeded(turn), false);
          assert.equal(turn.outcome, "NOT_ESTABLISHED", "the parent's own completion ran the verifier over the child's change");
          assert.equal(turn.reason, "VERIFIER_FAILED");
        } finally {
          agent.shutdown();
        }
      } finally {
        await gw.close();
        fs.rmSync(repo, { recursive: true, force: true });
      }
    });
  });

  test("a child report over unverified changes is not completion", async () => {
    await withHome(async () => {
      const gw = await gateway(delegating((r) => (toolResults(r.body) === 0 ? writeImplementation() : { text: "I wrote impl.mjs." })));
      const repo = makeRepo(VERIFIED_FIXTURE_FILES);
      try {
        const { turn, agent } = await directTurn(cfg(gw, repo, { authoritativeVerifierCommand: VERIFIED_FIXTURE_VERIFIER, trustedDeliverableFiles: ["impl.mjs"] }), "delegate the change");
        try {
          assert.match(delegationResult(agent), /Subagent did not complete: .*outcome=UNVERIFIED \(VERIFICATION_NOT_RUN\)/);
          assert.equal(turn.outcome, "VERIFIED", "the parent verified the child's change itself before completing");
        } finally {
          agent.shutdown();
        }
      } finally {
        await gw.close();
        fs.rmSync(repo, { recursive: true, force: true });
      }
    });
  });

  test("a child's change is the parent's change: the parent cannot finish as NOT_REQUIRED", async () => {
    await withHome(async () => {
      const gw = await gateway(delegating((r) => [writeImplementation(), done("sub verified")][toolResults(r.body)] ?? { text: "x" }));
      const repo = makeRepo(VERIFIED_FIXTURE_FILES);
      try {
        const { turn, agent } = await directTurn(cfg(gw, repo, { authoritativeVerifierCommand: VERIFIED_FIXTURE_VERIFIER, trustedDeliverableFiles: ["impl.mjs"] }), "delegate the change");
        try {
          assert.doesNotMatch(delegationResult(agent), /^Error/, "a verified child completes");
          assert.equal(turn.outcome, "VERIFIED");
          assert.ok(turn.verification?.command === VERIFIED_FIXTURE_VERIFIER, "verified by the parent's own verifier run");
        } finally {
          agent.shutdown();
        }
      } finally {
        await gw.close();
        fs.rmSync(repo, { recursive: true, force: true });
      }
    });
  });

  test("a read-only child report still completes (legitimate NOT_REQUIRED)", async () => {
    await withHome(async () => {
      const gw = await gateway(delegating((r) => (toolResults(r.body) === 0 ? read("notes.txt") : { text: "notes.txt says 42" })));
      const repo = makeRepo();
      try {
        const { turn, agent } = await directTurn(cfg(gw, repo), "delegate an investigation");
        try {
          assert.match(delegationResult(agent), /notes\.txt says 42/);
          assert.doesNotMatch(delegationResult(agent), /^Error/);
          assert.equal(turn.outcome, "NOT_REQUIRED");
          assert.equal(turnSucceeded(turn), true);
        } finally {
          agent.shutdown();
        }
      } finally {
        await gw.close();
        fs.rmSync(repo, { recursive: true, force: true });
      }
    });
  });
});

