async function withHome<T>(fn: (home: string) => Promise<T>): Promise<T> {
  const home = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-inv-home-"));
  const saved = Object.fromEntries(GATEWAY_KEYS.map((k) => [k, process.env[k]]));
