export type OperationEventType =
  | "RESOURCE_INELIGIBLE"
  | "RESOURCE_ELIGIBLE"
  | "WORK_STARTED"
  | "WORK_COMPLETED"
  | "WORK_REROUTED"
  | "WORK_PARKED"
  | "WORK_RESUMED"
  | "WORK_BLOCKED"
  | "CONTINUING_INDEPENDENT_WORK"
  | "OPERATION_WAITING"
  | "OPERATION_RESUMED"
  | "OPERATION_BLOCKED"
  | "OPERATION_COMPLETED"
  | "OPERATION_PAUSED"
  | "OPERATION_CANCELLED"
  | "DECISION_APPLIED"
  | "CONCURRENCY_LIMIT"
  | "INTEGRATION_QUEUED"
  | "INTEGRATION_SKIPPED"
  | "OPERATION_MESSAGE"
  | "OPERATION_MESSAGE_DROPPED"
  | "CHECKPOINT_RESTORED"
  | "WORK_INTEGRATED"
  | "WORKTREE_RETAINED";

export interface OperationEvent {
  type: OperationEventType;
  at: string;
  /** What it means, for the operator. */
  message: string;
  unitId?: string;
  resourceId?: string;
  detail?: Record<string, unknown>;
}

export interface OperationPolicy {
  /** How long the operation may wait with nothing runnable before asking for a decision. */
  maxWaitMs: number;
  /** Executions restarted after their outcome was lost; matches the UNKNOWN inference replay bound. */
  unknownResumeBudget: number;
  /** Runs of one unit before the scheduler stops retrying it. */
  maxRunsPerUnit: number;
  /** Floor between WAITING wake-ups. */
  minWaitMs: number;
  /**
   * Units that may run at once. Absent means 1, which is the v1.0.0 behaviour: exactly one unit in flight.
   * Bounded by `MAX_CONCURRENT_UNITS` and by the number of eligible resource slots (see `operation_schema`).
   */
  maxConcurrentUnits?: number;
}

export const DEFAULT_OPERATION_POLICY: OperationPolicy = {
  maxWaitMs: 12 * 60 * 60_000,
  unknownResumeBudget: 2,
  maxRunsPerUnit: 25,
  minWaitMs: 1_000,
};

/** One unit's worktree/branch in an isolated operation. */
export interface OperationGitUnit {
  branch: string;
  worktree: string;
  /** Integration tip the branch was created from. */
  baseCommit: string;
  /** Integration tip after the unit was merged (absent until it is). */
  integratedCommit?: string;
  /**
   * The unit whose uncommitted candidate this branch was snapshotted from (a failure_debugger on a dependency BLOCKED
   * on a failed verifier run). That candidate is unverified, so this branch is diagnostic and never integrated.
   */
  snapshotOf?: string;
  /** The `failedRun.at` of the dependency run this snapshot was taken from; a newer failure takes a fresh snapshot. */
  snapshotRun?: string;
}

/** Opt-in Git isolation for an operation (`spec.git.isolate`). */
export interface OperationGitState {
  candidate?: { digest: string; scope: "tree" | "commit" };
  /** The unit's executed verifier, copied verbatim from its result; absent when the unit produced none. */
  tests?: { command: string; status: string; hasExecutedTests: boolean; definitionBound?: false };
  /** 1-based merge order within the operation, assigned by the runner. */
  sequence?: number;
}

export interface DurableOperationState {
  /** Operation document version; see `operation_schema.ts`. Independent of the task-store envelope version. */
  schemaVersion: typeof CURRENT_OPERATION_SCHEMA_VERSION;
  id: string;
  objective: string;
  status: OperationStatus;
  createdAt: string;
  updatedAt: string;
  units: WorkUnit[];
  resources: ResourceDescriptor[];
  conditions: ResourceConditionRecord[];
  wait?: { since: string; wakeAt: string; reason: string; parkedUnits: string[] };
  blocked?: { since: string; decisions: EscalationDecision[] };
  events: OperationEvent[];
  policy: OperationPolicy;
  decisions?: AppliedDecision[];
  /** Present only for an isolated operation; absent keeps the original in-place behaviour. */
  git?: OperationGitState;
  /** SI-5: operator-declared boundary rules the review gate checks on each candidate diff (core/boundary_rules.ts). Absent: no boundary check. */
  boundaries?: BoundaryRules;
  /**
   * Non-isolated operations in a Git checkout: HEAD when the operation first ran. A review unit diffs against it, so
   * work a unit committed is still part of the candidate. Isolated operations use `git.baseCommit` instead.
   */
  startCommit?: string;
  /** Accepted unit integrations, oldest first. */
  integrations?: IntegrationReceipt[];
  /** Operator-created conversation snapshots, oldest first. */
  contextCheckpoints?: ContextCheckpoint[];
  /** Typed inter-unit messages, oldest first; bounded (see `operation_messages.ts`). */
  messages?: OperationMessage[];
  /** Highest message id ever issued. Kept so a pruned id is never reused (events cite message ids). */
  messageSeq?: number;
}

/** An option before it is numbered into a decision. */
export interface OptionSpec {
  label: string;
  action: DecisionAction;
}

/** A unit result the executor refused, kept verbatim (bounded) so the operator can see what the model said. */
export interface RejectedOutput {
  raw: string;
  reason: string;
}

/** A rejected output as the unit stores it. */
export interface StoredRejectedOutput extends RejectedOutput {
  at: string;
  truncated?: boolean;
}

/** The longest rejected output kept on a unit; the rest is cut and the record says so. */
export const MAX_REJECTED_OUTPUT_CHARS = 65_536;
/** How many rejected outputs a unit keeps (the most recent). */
export const MAX_REJECTED_OUTPUTS = 5;

export interface BlockSpec {
  cause: BlockCause;
  reason: string;
  question: string;
  options: OptionSpec[];
  /** Also offer assigning the unit to each other resource it may use (the scheduler knows which). */
  offerReassign?: boolean;
}

export type UnitRunResult =
  | {
      kind: "completed";
      summary: string;
      outcome: string;
      /** The verifier that produced the unit's outcome, for the integration check on the merged tree. */
      verification?: { command: string; status: string; hasExecutedTests: boolean; definitionBound?: false };
    }
  /** The resource could not take the work and nothing executed (or the condition is recorded at resource scope). */
  | { kind: "resource_unavailable"; failure: InferenceFailure; condition: ResourceConditionRecord }
  /** Inference may have executed and its bounded replays are spent: never resubmitted elsewhere automatically. */
  | { kind: "execution_unknown"; failure: InferenceFailure }
  | ({ kind: "failed" } & BlockSpec & {
      rejectedOutput?: RejectedOutput;
      /** The attempt ran a verifier that did not pass: kept on the unit for a dependent failure_debugger. */
      failedRun?: { summary: string; verification: { command: string; status: string; hasExecutedTests: boolean; definitionBound?: false } };
    })
  | { kind: "cancelled" };

export type Decision =
  | { kind: "run"; assignments: Assignment[] }
  | { kind: "wait"; wakeAt: number; reason: string; parked: string[] }
  | { kind: "complete" }
  | { kind: "blocked"; decisions: EscalationDecision[] };

