    resources: [{ id: "r1", endpoint: "https://api.test", model: "m" }],
  };
  assert.doesNotThrow(() => validateOperationSpec(valid));
  assert.doesNotThrow(() => validateOperationSpec(JSON.parse(JSON.stringify(valid))));

  const cases: Array<[unknown, RegExp]> = [
