//! Colour depth and theme tokens for the live TUI. The views draw with 24-bit colours; on a terminal that cannot show
//! them, `downsample` maps every cell of the finished frame to the nearest colour the terminal has (256 or 16), or
//! removes colour entirely (`NO_COLOR`, `TERM=dumb`), keeping bold/reverse so selection and emphasis survive.
use ratatui::{
    buffer::Buffer,
    style::{Color, Modifier},
};

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum Depth {
    #[default]
    TrueColor,
    Ansi256,
    Ansi16,
    Mono,
}

impl Depth {
    /// From the environment: `NEXUS_COLOR` (truecolor, 256, 16, none) overrides; a non-empty `NO_COLOR` or
    /// `TERM=dumb` means no colour; `COLORTERM=truecolor|24bit` means 24-bit; a `TERM` naming 256 colours means 256;
    /// anything else is assumed to have the 16 standard colours.
    pub fn detect(var: impl Fn(&str) -> Option<String>) -> Depth {
        let get = |name: &str| var(name).filter(|value| !value.is_empty());
        if let Some(choice) = get("NEXUS_COLOR") {
            match choice.to_ascii_lowercase().as_str() {
                "truecolor" | "24bit" | "24" => return Depth::TrueColor,
                "256" => return Depth::Ansi256,
                "16" | "ansi" => return Depth::Ansi16,
                "none" | "mono" | "0" | "off" => return Depth::Mono,
                _ => {}
            }
        }
        if get("NO_COLOR").is_some() {
            return Depth::Mono;
        }
        let term = get("TERM").unwrap_or_default();
        if term == "dumb" {
            return Depth::Mono;
        }
        if matches!(get("COLORTERM").as_deref(), Some("truecolor" | "24bit")) {
            return Depth::TrueColor;
        }
        if term.contains("256color") {
            return Depth::Ansi256;
        }
        Depth::Ansi16
    }

    pub fn from_env() -> Depth {
        Depth::detect(|name| std::env::var(name).ok())
    }
}

pub fn apply_backend_policy(depth: Depth) {
    crossterm::style::force_color_output(depth != Depth::Mono);
}

/// A writer that turns the 256-colour SGR crossterm writes for named and low indexed colours (`38;5;0..15`, which
/// 8/16-colour terminals and the Linux console ignore or misread) into the classic `30-37`/`90-97`/`40-47`/`100-107`
/// codes. It buffers until `flush` (ratatui flushes once per frame), so a sequence is never split across two writes.
/// Pass-through when `sixteen` is false.
pub struct SgrWriter<W: std::io::Write> {
    inner: W,
    buf: Vec<u8>,
    sixteen: bool,
}

impl<W: std::io::Write> SgrWriter<W> {
    pub fn new(inner: W, sixteen: bool) -> Self {
        SgrWriter { inner, buf: Vec::new(), sixteen }
    }
}

impl<W: std::io::Write> std::io::Write for SgrWriter<W> {
    fn write(&mut self, data: &[u8]) -> std::io::Result<usize> {
        if self.sixteen {
            self.buf.extend_from_slice(data);
            Ok(data.len())
        } else {
            self.inner.write(data)
        }
    }

    fn flush(&mut self) -> std::io::Result<()> {
        if !self.buf.is_empty() {
            let out = rewrite_sgr(&self.buf);
            self.buf.clear();
            self.inner.write_all(&out)?;
        }
        self.inner.flush()
    }
}

fn basic_code(index: u8, background: bool) -> u16 {
    let base = if background { 40 } else { 30 };
    u16::from(index) + if index < 8 { base } else { base + 52 }
}

/// Rewrites `CSI ... m` sequences whose `38;5;N` / `48;5;N` name one of the 16 basic colours. Everything else
/// (other CSI, OSC strings such as a clipboard write, truncated sequences, plain text) is copied unchanged.
pub fn rewrite_sgr(input: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(input.len());
    let mut i = 0;
    while i < input.len() {
        if input[i] != 0x1b {
            out.push(input[i]);
            i += 1;
            continue;
        }
        match input.get(i + 1) {
            Some(b'[') => {
                let start = i + 2;
                let mut end = start;
                while end < input.len() && (0x20..=0x3f).contains(&input[end]) {
                    end += 1;
                }
                match input.get(end) {
                    Some(b'm') if input[start..end].iter().all(|b| b.is_ascii_digit() || *b == b';') => {
                        out.extend_from_slice(b"\x1b[");
                        out.extend_from_slice(rewrite_sgr_params(&input[start..end]).as_bytes());
                        out.push(b'm');
                        i = end + 1;
                    }
                    Some(_) => {
                        out.extend_from_slice(&input[i..=end]);
                        i = end + 1;
                    }
                    None => {
                        out.extend_from_slice(&input[i..]);
                        i = input.len();
                    }
                }
            }
            Some(b']') => {
                // An OSC string runs to BEL or ST; it is copied whole.
                let mut end = i + 2;
                while end < input.len() && input[end] != 0x07 && !(input[end] == 0x1b && input.get(end + 1) == Some(&b'\\')) {
                    end += 1;
                }
                let stop = if end < input.len() && input[end] == 0x1b { end + 2 } else { end + 1 };
                let stop = stop.min(input.len());
                out.extend_from_slice(&input[i..stop]);
                i = stop;
            }
            _ => {
                out.push(0x1b);
                i += 1;
            }
        }
    }
    out
}

fn rewrite_sgr_params(params: &[u8]) -> String {
    let text = String::from_utf8_lossy(params);
    let tokens: Vec<&str> = text.split(';').collect();
    let mut out: Vec<String> = Vec::with_capacity(tokens.len());
    let mut i = 0;
    while i < tokens.len() {
        let background = tokens[i] == "48";
        if (background || tokens[i] == "38") && tokens.get(i + 1) == Some(&"5") {
            if let Some(index) = tokens.get(i + 2).and_then(|t| t.parse::<u8>().ok()).filter(|n| *n < 16) {
                out.push(basic_code(index, background).to_string());
                i += 3;
                continue;
            }
            // Another indexed colour: copy the three tokens as they are.
            let take = (i + 3).min(tokens.len());
            out.extend(tokens[i..take].iter().map(|t| t.to_string()));
            i = take;
            continue;
        }
        if (background || tokens[i] == "38") && tokens.get(i + 1) == Some(&"2") {
            let take = (i + 5).min(tokens.len());
            out.extend(tokens[i..take].iter().map(|t| t.to_string()));
            i = take;
            continue;
        }
        out.push(tokens[i].to_string());
        i += 1;
    }
    out.join(";")
}

/// Maps the colours of every cell to what `depth` can show. A no-op for 24-bit terminals.
pub fn downsample(buffer: &mut Buffer, depth: Depth) {
    if depth == Depth::TrueColor {
        return;
    }
    for cell in buffer.content.iter_mut() {
        if depth == Depth::Mono {
            // A background carried meaning (selection, the status bar, a badge): reverse video keeps it visible.
            if !matches!(cell.bg, Color::Reset) {
                cell.modifier.insert(Modifier::REVERSED);
            }
            cell.fg = Color::Reset;
            cell.bg = Color::Reset;
            continue;
        }
        cell.fg = reduce(cell.fg, depth);
        cell.bg = reduce(cell.bg, depth);
    }
}

fn reduce(color: Color, depth: Depth) -> Color {
    match (color, depth) {
        (Color::Rgb(r, g, b), Depth::Ansi256) => Color::Indexed(nearest_256(r, g, b)),
        (Color::Rgb(r, g, b), Depth::Ansi16) => nearest_16(r, g, b),
        (Color::Indexed(index), Depth::Ansi16) if index >= 16 => {
            let (r, g, b) = rgb_of_256(index);
            nearest_16(r, g, b)
        }
        _ => color,
    }
}

const CUBE: [u8; 6] = [0, 95, 135, 175, 215, 255];

fn distance(a: (u8, u8, u8), b: (u8, u8, u8)) -> u32 {
    let d = |x: u8, y: u8| (i32::from(x) - i32::from(y)).pow(2) as u32;
}

fn draw_snapshot<B: ratatui::backend::Backend>(
    terminal: &mut Terminal<B>,
    snapshot: &Snapshot,
    state: &mut AppState,
    depth: theme::Depth,
) -> Result<(), B::Error> {
    terminal.draw(|frame| {
        render(frame, snapshot, state);
        theme::downsample(frame.buffer_mut(), depth);
    })?;
    Ok(())
}

fn badge_style(theme: &str) -> Style {
    if theme == "monochrome" {
        Style::default().add_modifier(Modifier::BOLD | Modifier::REVERSED)
    } else {
        Style::default()
            .fg(Color::Black)
            .bg(theme_accent(theme))
            .add_modifier(Modifier::BOLD)
    }
}

fn semantic_style(theme: &str, color: Color) -> Style {
    if theme == "monochrome" {
        let modifier = match color {
            Color::Green => Modifier::BOLD,
            Color::Yellow => Modifier::UNDERLINED,
            Color::Red => Modifier::REVERSED,
            _ => Modifier::empty(),
        };
        Style::default().fg(Color::Reset).add_modifier(modifier)
    } else {
        Style::default().fg(color)
    }
}

fn render(frame: &mut ratatui::Frame, data: &Snapshot, state: &mut AppState) {
    let area = frame.area();
    if area.width < 58 || area.height < 14 {
        frame.render_widget(
            Paragraph::new("Nexus needs a wider terminal (58×14 minimum). Press q to return.")
                .style(Style::default().fg(theme_accent(&data.theme))),
            area,
        );
        return;
    }

    let root = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3),
            Constraint::Min(5),
            Constraint::Length(2),
        ])
        .split(area);
    render_header(frame, root[0], data);

    // A wide but short terminal still needs the compact, stacked context layout: beside activity it would clip the
    // validation summary and active milestone below the fold. Side-by-side earns its space once both dimensions fit.
    let columns = if area.width >= 96 && area.height >= 24 {
        Layout::default()
            .direction(Direction::Horizontal)
            .constraints([Constraint::Percentage(62), Constraint::Percentage(38)])
            .split(root[1])
    } else {
        Layout::default()
            .direction(Direction::Vertical)
            .constraints([Constraint::Percentage(64), Constraint::Percentage(36)])
            .split(root[1])
    };
    render_activity(frame, columns[0], data, state);
    render_context(frame, columns[1], data);
    render_footer(frame, root[2], data);

    match state.overlay {
        Overlay::None => {}
        Overlay::Detail => render_detail(frame, data, state),
        Overlay::Help => render_help(frame, data, state),
        Overlay::Validation => render_validation(frame, data, state),
    }
}

fn render_header(frame: &mut ratatui::Frame, area: Rect, data: &Snapshot) {
    let rows = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Length(1), Constraint::Length(1)])
        .split(area);
    let status_color = match data.status.as_str() {
        "VERIFIED" | "COMPLETE" | "NO CHANGES" | "IDLE" => Color::Green,
        "UNVERIFIED" | "STOPPING" | "BLOCKED" | "LIMIT_REACHED" | "INCOMPLETE" => Color::Yellow,
        "FAILED" | "INTERRUPTED" | "NEEDS ATTENTION" => Color::Red,
        _ => theme_accent(&data.theme),
    };
    let mut top_spans = vec![
        Span::styled(
            " NEXUS ",
            badge_style(&data.theme),
        ),
        Span::styled(
            "  WORKSPACE  ",
            Style::default().fg(MUTED).add_modifier(Modifier::BOLD),
        ),
        Span::styled(
            short_path(&data.workspace, if area.width < 82 { 16 } else { 28 }),
            Style::default().fg(Color::Reset),
        ),
    ];
    if area.width >= 82 {
        top_spans.extend([
            Span::raw("   "),
            Span::styled(one_line(&data.model, 20), Style::default().fg(MUTED)),
        ]);
    }
    top_spans.extend([
        Span::raw("   "),
        Span::styled(
            one_line(&data.status, (area.width / 3) as usize),
            semantic_style(&data.theme, status_color).add_modifier(Modifier::BOLD),
        ),
    ]);
    let top = Line::from(top_spans);
    frame.render_widget(
        Paragraph::new(top).style(Style::default().bg(SURFACE)),
        rows[0],
    );
    frame.render_widget(
        Paragraph::new(Line::from(vec![
            Span::styled(
                " OBJECTIVE  ",
                Style::default()
                    .fg(theme_accent(&data.theme))
                    .add_modifier(Modifier::BOLD),
            ),
            Span::styled(
                one_line(&data.objective, area.width.saturating_sub(14) as usize),
                Style::default().fg(Color::Reset),
            ),
        ])),
        rows[1],
    );
}

fn render_activity(frame: &mut ratatui::Frame, area: Rect, data: &Snapshot, state: &mut AppState) {
    let items = if data.activity.is_empty() {
        vec![ListItem::new(Line::from(Span::styled(
            "No work recorded yet. Start with a prompt in the REPL.",
            Style::default().fg(MUTED),
        )))]
    } else {
        data.activity
            .iter()
            .enumerate()
            .map(|(index, event)| {
                let (glyph, color) = match event.kind.as_str() {
                    "finding" => ("✳", Color::Yellow),
                    "failure" => ("×", Color::Red),
                    "warning" => ("!", Color::Yellow),
                    "change" => ("▸", theme_accent(&data.theme)),
                    "tool" => ("·", MUTED),
                    _ => ("◦", Color::Reset),
                };
                let marker = if index == state.selected { "›" } else { " " };
                ListItem::new(vec![
                    Line::from(vec![
                        Span::styled(
                            format!("{marker} {glyph} "),
                            semantic_style(&data.theme, color).add_modifier(Modifier::BOLD),
                        ),
                        Span::styled(
                            diff_view::safe_text(&event.title),
                            Style::default()
                                .fg(Color::Reset)
                                .add_modifier(Modifier::BOLD),
                        ),
                    ]),
                    Line::from(Span::styled(
                        format!(
                            "    {}",
                            one_line(&event.summary, area.width.saturating_sub(8) as usize)
                        ),
                        Style::default().fg(MUTED),
                    )),
                ])
            })
            .collect()
    };
    let list = List::new(items)
        .block(
            Block::default()
                .borders(Borders::LEFT)
                .border_style(Style::default().fg(MUTED))
                .title(Span::styled(
                    "  RECENT SIGNAL  ",
                    Style::default()
                        .fg(theme_accent(&data.theme))
                        .add_modifier(Modifier::BOLD),
                )),
        )
        .highlight_style(Style::default().add_modifier(Modifier::REVERSED));
    let mut list_state =
        ListState::default().with_selected((!data.activity.is_empty()).then_some(state.selected));
    frame.render_stateful_widget(list, area, &mut list_state);
}

