  17	
  18	impl Depth {
  19	    /// From the environment: `NEXUS_COLOR` (truecolor, 256, 16, none) overrides; a non-empty `NO_COLOR` or
  20	    /// `TERM=dumb` means no colour; `COLORTERM=truecolor|24bit` means 24-bit; a `TERM` naming 256 colours means 256;
  21	    /// anything else is assumed to have the 16 standard colours.
  22	    pub fn detect(var: impl Fn(&str) -> Option<String>) -> Depth {
  23	        let get = |name: &str| var(name).filter(|value| !value.is_empty());
  24	        if let Some(choice) = get("NEXUS_COLOR") {
  25	            match choice.to_ascii_lowercase().as_str() {
  26	                "truecolor" | "24bit" | "24" => return Depth::TrueColor,
  27	                "256" => return Depth::Ansi256,
  28	                "16" | "ansi" => return Depth::Ansi16,
  29	                "none" | "mono" | "0" | "off" => return Depth::Mono,
  30	                _ => {}
  31	            }
  32	        }
  33	        if get("NO_COLOR").is_some() {
  34	            return Depth::Mono;
  35	        }
  36	        let term = get("TERM").unwrap_or_default();
  37	        if term == "dumb" {
  38	            return Depth::Mono;
  39	        }
  40	        if matches!(get("COLORTERM").as_deref(), Some("truecolor" | "24bit")) {
  41	            return Depth::TrueColor;
  42	        }
  43	        if term.contains("256color") {
  44	            return Depth::Ansi256;
  45	        }
  46	        Depth::Ansi16
  47	    }
