   674	fn one_line(value: &str, max: usize) -> String {
   675	    let normalized = value.split_whitespace().collect::<Vec<_>>().join(" ");
   676	    let clean = diff_view::safe_text(&normalized);
   677	    if max == 0 {
   678	        return String::new();
   679	    }
   680	    if unicode_width::UnicodeWidthStr::width(clean.as_str()) <= max {
   681	        clean
   682	    } else {
   683	        let mut clipped = String::new();
   684	        let mut width: usize = 0;
   685	        for grapheme in unicode_segmentation::UnicodeSegmentation::graphemes(clean.as_str(), true) {
   686	            let grapheme_width = unicode_width::UnicodeWidthStr::width(grapheme);
   687	            if width.saturating_add(grapheme_width) > max - 1 {
   688	                break;
   689	            }
   690	            clipped.push_str(grapheme);
   691	            width += grapheme_width;
   692	        }
   693	        format!("{clipped}…")
   694	    }
   695	}
