const ACCENT: Color = Color::Cyan;
const MUTED: Color = Color::Reset;
const SURFACE: Color = Color::Reset;

fn theme_accent(theme: &str) -> Color {
    match theme {
        "catppuccin" | "nord" => Color::Cyan,
        "dracula" => Color::Magenta,
        "monochrome" => Color::Reset,
        _ => ACCENT,
    }
}

#[derive(Clone, Debug, Deserialize)]
struct Snapshot {
    model: String,
    workspace: String,
    task_id: String,
    objective: String,
    activity: Vec<Activity>,
    plan: Vec<Milestone>,
    validation: Option<Validation>,
    context: String,
    status: String,
    #[serde(default)]
    theme: String,
}

#[derive(Clone, Debug, Deserialize)]
struct Activity {
    kind: String,
    title: String,
    summary: String,
    detail: String,
}

#[derive(Clone, Debug, Deserialize)]
struct Milestone {
    name: String,
    status: String,
}

#[derive(Clone, Debug, Deserialize)]
struct Validation {
    status: String,
    candidate_id: Option<String>,
    verifier: Option<String>,
}

#[derive(Default)]
struct AppState {
    selected: usize,
    scroll: u16,
    overlay: Overlay,
    done: bool,
}

#[derive(Default, PartialEq)]
enum Overlay {
    #[default]
    None,
    Detail,
    Help,
    Validation,
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut args = env::args_os().skip(1);
    let first = args.next().ok_or(
        "usage: nexus-tui [--plain] SNAPSHOT.json\n       nexus-tui --live [--check] [--sidecar PATH] [--node BIN] [-- SIDECAR_ARGS...]",
    )?;
    if first == "--live" {
        let rest = args.map(|arg| arg.to_string_lossy().into_owned()).collect();
        std::process::exit(live::main(rest, &mut io::stderr()));
    }
    if first == "--check" {
        let rest = vec!["--check".to_string()];
        std::process::exit(live::main(rest, &mut io::stderr()));
    }
    if first == "--version" {
        println!("{}", env!("CARGO_PKG_VERSION"));
        return Ok(());
    }
    let plain = first == "--plain";
    let snapshot_path = PathBuf::from(if plain {
        args.next()
            .ok_or("usage: nexus-tui --plain SNAPSHOT.json")?
    } else {
        first
    });
    let snapshot: Snapshot = serde_json::from_slice(&fs::read(&snapshot_path)?)?;
    if plain {
        let backend = TestBackend::new(100, 30);
        let mut terminal = Terminal::new(backend)?;
        terminal.draw(|frame| render(frame, &snapshot, &mut AppState::default()))?;
        print!("{}", terminal.backend());
        return Ok(());
    }
    if !io::stdin().is_terminal() || !io::stdout().is_terminal() {
        return Err("interactive Nexus TUI requires a terminal".into());
    }

    let depth = theme::Depth::from_env();
    theme::apply_backend_policy(depth);
    drop(ratatui::try_init()?);
    let backend = ratatui::backend::CrosstermBackend::new(theme::SgrWriter::new(
        io::stdout(),
        depth == theme::Depth::Ansi16,
    ));
    let mut terminal = Terminal::new(backend)?;
    let result = run(&mut terminal, &snapshot, depth);
    ratatui::restore();
    result?;
    Ok(())
}

