pub fn content_rows(text: &str, lang: Option<&Lang>, width: usize, fit: Fit, pal: &Palette, fg: Color, bg: Option<Color>) -> Vec<(Vec<Span<'static>>, usize)> {
    let base = bg.map_or_else(Style::default, |bg| Style::default().bg(bg));
